import{_ as l,l as i,o as e,c as s,v as t,p as n,x as r,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"类型检查","description":"","frontmatter":{"title":"类型检查","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/typecheck.md","filePath":"cs/typecheck.md","lastUpdated":1789023840000}'),h={name:"cs/typecheck.md"};function E(_,a,f,m,B,u){const o=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="类型检查" tabindex="-1">类型检查 <a class="header-anchor" href="#类型检查" aria-label="Permalink to &quot;类型检查&quot;">​</a></h1><div class="epigraph"><p>每个表达式在绑定之后还有一个类型；运算符与赋值要求操作数属于规定的类型，否则程序不进入翻译。</p><footer>—— 据龙书第 6 章；Cardelli, Type Systems, 1996 整理</footer></div><p>上一课<a href="/cs/name-resolution">名字解析</a>把名字绑到声明。本课不重做查找。缺口是：声明带着类型，表达式要<strong>综合</strong>出类型，并与上下文的期望<strong>比对</strong>。通过才交给 IR；失败则拒绝编译。本课只钉静态、简单类型（整数、指针、函数、数组），不写多态推断全文。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>绑定只回答「是哪一个 x」，不回答「x+1 是否合法」。算术、下标、调用、赋值各有规则。缺口是语法制导的类型规则：叶从符号表取，内节点由孩子类型计算。隐式转换若允许，必须写进规则，不能 silently 在后端出现。</p><p><a href="/cs/fixed-and-float">组成课的定点与浮点</a>说明表示不同；本课决定的是<strong>语言层</strong>的类型，不是 IEEE 编码。</p><h3 id="检查不是「运行时-typeof」" tabindex="-1">检查不是「运行时 typeof」 <a class="header-anchor" href="#检查不是「运行时-typeof」" aria-label="Permalink to &quot;检查不是「运行时 typeof」&quot;">​</a></h3><p>静态检查在编译期拒绝一整类错误。动态类型语言把检查推迟，编译课主干仍生成需类型已知的 IR。本课不把解释器的 tag 当类型系统。</p><p><span class="marginnote">龙书 6.5 节类型表达式与结构等价/名等价。Cardelli 的综述把规则写成推导。本课用结构等价足够：数组与记录比字段。Hindley–Milner 不进主干。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>定义类型表达式。声明把类型写入符号记录。遍历 AST：二元运算要求两操作数一致（或可转换）；调用比较实参与形参； return 与函数返回类型。错误收集后可继续查，避免一次只报一个。</p>',11)),(e(),n(c,null,{default:r(()=>[p(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20AST%5B%22%E5%B7%B2%E7%BB%91%E5%AE%9A%20AST%22%5D%20--%3E%20INF%5B%22%E7%BB%BC%E5%90%88%E7%B1%BB%E5%9E%8B%22%5D%0A%20%20INF%20--%3E%20CHK%5B%22%E4%B8%8E%E6%9C%9F%E6%9C%9B%E6%AF%94%E5%AF%B9%22%5D%0A%20%20CHK%20--%3E%20IR%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9AIR%22%5D%0A%20%20CHK%20--%3E%20ERR%5B%22%E7%B1%BB%E5%9E%8B%E9%94%99%E8%AF%AF%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>void、指针解引用、数组退化为指针按语言写清，不要混成「都是 int」。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>类型通过后，每个节点有固定类型，IR 生成知道宽度与符号性，<a href="/cs/twos-complement">补码</a>的运算种类可选。重载决议在本课用类型选声明，符号表查找键含类型。</p><p>不健全的转换（强制转型）是显式节点，后课仍生成，但责任在源。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不生成三地址、不做生命周期与借用。不证类型系统的进展与保持（那是 PL 理论附录）。子类型与接口只点名。后课默认：能进 IR 的程序类型正确。线性 IR 是下一课把树压成指令序列。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>类型在已绑定 AST 上综合与比对。</li><li>静态拒绝非法运算；转换为显式规则。</li><li>通过后宽度已知，供 IR 使用。</li><li>出处：Aho et al., 龙书第 6 章。</li></ul>',8))])}const x=l(h,[["render",E]]);export{T as __pageData,x as default};
